module.exports = "<ion-header class=\"interior-header\" dir=\"rtl\">\n  \n  <app-page-header titleKey=\"pageHeader.tuner-plus/clock-learning/clock-learning\" fallback=\"/TunerPlus\">\n\n  </app-page-header>\n</ion-header>\n\n<ion-content dir=\"rtl\" class=\"clock-content\">\n  <div class=\"container\">\n    <div class=\"hero-banner\">\n      <span class=\"hero-chip\">⏰ آموزش زمان و ساعت کلاس اول</span>\n      <h1>ساعت‌آموز تعاملی کودکانه</h1>\n      <p>آشنایی با عقربه کوچک (ساعت‌شمار)، عقربه بزرگ (دقیقه‌شمار)، مفهوم ساعت‌های کامل و نیم در کتاب ریاضی اول دبستان.</p>\n    </div>\n\n    <div class=\"clock-workspace\">\n      <!-- سمت چپ: صفحه ساعت آنالوگ و دیجیتال -->\n      <div class=\"clock-display-card\">\n        <div class=\"analog-clock\">\n          <div class=\"clock-face\">\n            <!-- اعداد ۱ تا ۱۲ دور ساعت -->\n            <span class=\"num num-12\">۱۲</span>\n            <span class=\"num num-1\">۱</span>\n            <span class=\"num num-2\">۲</span>\n            <span class=\"num num-3\">۳</span>\n            <span class=\"num num-4\">۴</span>\n            <span class=\"num num-5\">۵</span>\n            <span class=\"num num-6\">۶</span>\n            <span class=\"num num-7\">۷</span>\n            <span class=\"num num-8\">۸</span>\n            <span class=\"num num-9\">۹</span>\n            <span class=\"num num-10\">۱۰</span>\n            <span class=\"num num-11\">۱۱</span>\n\n            <!-- عقربه ساعت (کوتاه و آبی) -->\n            <div class=\"hand hour-hand\" [style.transform]=\"'rotate(' + hourAngle + 'deg)'\"></div>\n\n            <!-- عقربه دقیقه (بلند و قرمز) -->\n            <div class=\"hand minute-hand\" [style.transform]=\"'rotate(' + minuteAngle + 'deg)'\"></div>\n\n            <div class=\"center-pin\"></div>\n          </div>\n        </div>\n\n        <!-- نمایش دیجیتال و خواندن متنی -->\n        <div class=\"digital-box\">\n          <div class=\"time-digit\">\n            <span>{{ hours < 10 ? '۰' + hours : hours }} : {{ minutes < 10 ? '۰' + minutes : minutes }}</span>\n          </div>\n          <div class=\"persian-spoken-time\">\n            🗣 {{ getPersianTimeText() }}\n          </div>\n        </div>\n\n        <div class=\"hands-legend\">\n          <span class=\"legend-item hour\"><span class=\"dot blue\"></span> عقربه کوچک: ساعت‌شمار</span>\n          <span class=\"legend-item minute\"><span class=\"dot red\"></span> عقربه بزرگ: دقیقه‌شمار</span>\n        </div>\n      </div>\n\n      <!-- سمت راست: کنترلرها و بازی مسابقه -->\n      <div class=\"clock-controls-card\">\n        <h3>تنظیم ساعت و دقیقه</h3>\n\n        <div class=\"slider-row\">\n          <label>ساعت (۱ تا ۱۲): <b>{{ hours }}</b></label>\n          <input type=\"range\" min=\"1\" max=\"12\" step=\"1\" [(ngModel)]=\"hours\" (input)=\"updateClockHands()\" />\n        </div>\n\n        <div class=\"slider-row\">\n          <label>دقیقه: <b>{{ minutes }}</b> (روی ۰ یا ۳۰)</label>\n          <div class=\"quick-min-btns\">\n            <button [class.active]=\"minutes === 0\" (click)=\"setMinute(0)\">۰۰ (تمام)</button>\n            <button [class.active]=\"minutes === 30\" (click)=\"setMinute(30)\">۳۰ (نیم)</button>\n            <button [class.active]=\"minutes === 15\" (click)=\"setMinute(15)\">۱۵ (ربع)</button>\n            <button [class.active]=\"minutes === 45\" (click)=\"setMinute(45)\">۴۵</button>\n          </div>\n        </div>\n\n        <div class=\"presets-section\">\n          <h4>ساعت‌های مهم برنامه روزانه:</h4>\n          <div class=\"presets-grid\">\n            <button *ngFor=\"let p of presets\" class=\"preset-btn\" (click)=\"applyPreset(p)\">\n              {{ p.label }}\n            </button>\n          </div>\n        </div>\n\n        <!-- مینی کوئیز ساعت -->\n        <div class=\"clock-quiz-box\">\n          <div class=\"quiz-title-row\">\n            <h4>🎯 آزمون: عقربه‌ها را تنظیم کن!</h4>\n            <span class=\"quiz-badge\">امتیاز: {{ quizScore }}</span>\n          </div>\n          <p class=\"target-time-prompt\">\n            عقربه‌ها را طوری قرار بده که نشان دهد:\n            <b class=\"highlight-target\">ساعت {{ quizTargetHour }} و {{ quizTargetMinute === 0 ? '۰۰ (تمام)' : '۳۰ دقیقه (نیم)' }}</b>\n          </p>\n\n          <div class=\"quiz-actions\">\n            <button class=\"check-btn\" (click)=\"checkQuiz()\">بررسی پاسخ من ✔️</button>\n            <button class=\"next-quiz-btn\" (click)=\"generateClockQuiz()\">معمای جدید ❯</button>\n          </div>\n\n          <div *ngIf=\"quizAnswered\" class=\"quiz-result-msg\">\n            <span *ngIf=\"quizFeedback === 'correct'\" class=\"correct-msg\">🎉 آفرین قهرمان! ساعت دقیقاً درست تنظیم شد!</span>\n            <span *ngIf=\"quizFeedback === 'wrong'\" class=\"wrong-msg\">❌ دقت کن عزیزم، عقربه کوچک روی {{ quizTargetHour }} و بزرگ روی {{ quizTargetMinute === 0 ? '۱۲' : '۶' }} باشد.</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <app-footer></app-footer>\n</ion-content>\n";

